      C("She had her passport ___ at the airport.", ["stolen", "steal", "stealing"], "stolen", "Неприємність → had … stolen.", "Неприятность → had … stolen.", tp="causative-have"),
      C("Where do you get your nails ___ ?", ["done", "do", "doing"], "done", "Get … done.", tp="causative-have"),
