      X("I'm having repaired my car.", "I'm having my car repaired.", "Have + об'єкт + V3.", "Have + объект + V3.", acc=["I'm getting my car repaired."], tp="causative-have"),
      T("Мені треба полагодити телефон (у сервісі).", "Мне нужно починить телефон (в сервисе).", "I need to get my phone repaired.", "Get … repaired.", acc=["I need to have my phone repaired.", "I need to get my phone fixed.", "I need to have my phone fixed."], tp="causative-have"),
